# Homebrew cask for Playfin (generated by scripts/update-cask.sh for each version).
cask "playfin" do
  version "0.10.0"
  sha256 "4011eeac0db1338977bba6e5526f7aa11241e67ffe9e05327a7b1fe3010b4afd"

  url "https://github.com/playfin-app/playfin/releases/download/v#{version}/Playfin-macOS.zip"
  name "Playfin"
  desc "Fast native client for Jellyfin media servers"
  homepage "https://github.com/playfin-app/playfin"

  depends_on macos: :sonoma

  app "Playfin.app"

  # Unnotarised build (no Apple Developer account): we remove the quarantine so the app opens.
  # Kept as `postflight`: the newer `postflight_steps` has no step that can remove the quarantine.
  postflight do
    system_command "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "#{appdir}/Playfin.app"]
  end

  zap trash: [
    "~/Library/Application Support/com.playfin.app",
    "~/Library/Caches/com.playfin.app",
    "~/Library/Preferences/com.playfin.app.plist",
  ]
end
